import Foundation

public protocol FreightAtlasProviding: Sendable {
    func freightAtlas() async throws -> FreightAtlas
}

/// Loads the freight atlas generated by `scripts/freight_atlas/build.py` from the app bundle.
public struct BundledFreightAtlasService: FreightAtlasProviding {
    public static let resourceName = "freight-atlas"

    private let url: URL?

    public init(url: URL? = BundledFreightAtlasService.defaultURL) {
        self.url = url
    }

    public static var defaultURL: URL? {
        #if SWIFT_PACKAGE
        Bundle.module.url(forResource: resourceName, withExtension: "json")
        #else
        Bundle.main.url(forResource: resourceName, withExtension: "json")
        #endif
    }

    public func freightAtlas() async throws -> FreightAtlas {
        guard let url else { throw RailDataError.unavailable }
        let data = try Data(contentsOf: url)
        return try FreightAtlasDecoder.decode(data)
    }
}

/// Decodes the compact freight atlas JSON (encoded polylines, short keys) into model values.
public enum FreightAtlasDecoder {
    public static func decode(_ data: Data) throws -> FreightAtlas {
        let file = try JSONDecoder().decode(AtlasFile.self, from: data)
        let bounds = file.tierBounds

        let corridors = file.corridors.enumerated().compactMap { index, corridor -> FreightCorridor? in
            guard let railroad = RailOperator(rawValue: corridor.rr) else { return nil }
            let path = Polyline.decode(corridor.path)
            guard path.count >= 2 else { return nil }
            return FreightCorridor(
                id: index,
                railroad: railroad,
                trainsPerDay: corridor.tpd,
                maxSpeedMPH: corridor.mph,
                mainTracks: corridor.tracks,
                crossingCount: corridor.n,
                level: TrafficLevel(trainsPerDay: corridor.tpd, bounds: bounds),
                place: corridor.place,
                path: path
            )
        }

        let terminals = file.terminals.map { terminal in
            IntermodalTerminal(
                id: terminal.id,
                name: terminal.name,
                city: terminal.city,
                state: terminal.state,
                port: terminal.port,
                operatorsDescription: terminal.operators,
                railroads: terminal.railroads.compactMap(RailOperator.init(rawValue:)),
                handlesTrailers: terminal.trailers,
                handlesContainers: terminal.containers,
                coordinate: RailCoordinate(latitude: terminal.lat, longitude: terminal.lon)
            )
        }

        let service = file.service.railroads.compactMap { report -> RailroadServiceReport? in
            guard let railroad = RailOperator(rawValue: report.railroad) else { return nil }
            let speeds = report.speedMPH
                .filter { $0.key != "system" }
                .map { RailroadServiceReport.TrainSpeed(trainType: trainTypeLabel($0.key), mph: $0.value) }
                .sorted { $0.mph == $1.mph ? $0.trainType < $1.trainType : $0.mph > $1.mph }
            return RailroadServiceReport(
                railroad: railroad,
                systemSpeedMPH: report.speedMPH["system"],
                speeds: speeds,
                systemDwellHours: report.systemDwellHours,
                carsOnline: report.carsOnline,
                trainsHeldPerDay: report.trainsHeldPerDay,
                yards: report.terminals.map {
                    YardDwell(
                        railroad: railroad,
                        name: $0.name,
                        coordinate: RailCoordinate(latitude: $0.lat, longitude: $0.lon),
                        dwellHours: $0.dwellHours
                    )
                }
            )
        }

        let volume = file.volume.flatMap { volume -> FreightVolumeReport? in
            guard let weekEnded = ReportDate(iso: volume.weekEnded) else { return nil }
            return FreightVolumeReport(
                week: volume.week,
                weekEnded: weekEnded,
                carloads: volume.totalCarloads.figure,
                intermodalUnits: volume.intermodalUnits.figure,
                totalTraffic: volume.totalTraffic.figure,
                commodities: volume.commodities
                    .map { FreightVolumeReport.Commodity(name: $0.name, carloads: $0.carloads, changePercent: $0.changePercent) }
                    .sorted { $0.carloads > $1.carloads }
            )
        }

        let sources = file.sources.map {
            FreightDataSource(
                id: $0.id,
                name: $0.name,
                publisher: $0.publisher,
                url: URL(string: $0.url),
                asOf: $0.asOf,
                detail: $0.detail
            )
        }

        return FreightAtlas(
            corridors: corridors,
            terminals: terminals,
            serviceWeekEnded: ReportDate(iso: file.service.weekEnded),
            service: service,
            volume: volume,
            sources: sources,
            levelBounds: bounds
        )
    }

    static func trainTypeLabel(_ key: String) -> String {
        switch key {
        case "intermodal": "Intermodal"
        case "grain": "Grain"
        case "coal": "Coal"
        case "automotive": "Automotive"
        case "crudeOil": "Crude oil"
        case "ethanol": "Ethanol"
        case "manifest": "Mixed freight"
        default: String(key.prefix(1)).uppercased() + String(key.dropFirst())
        }
    }

    private struct AtlasFile: Decodable {
        let sources: [Source]
        let tierBounds: [Double]
        let corridors: [Corridor]
        let terminals: [Terminal]
        let service: Service
        let volume: Volume?
    }

    private struct Source: Decodable {
        let id: String
        let name: String
        let publisher: String
        let url: String
        let asOf: String
        let detail: String
    }

    private struct Corridor: Decodable {
        let rr: String
        let tpd: Double?
        let mph: Int?
        let tracks: Int?
        let n: Int
        let place: String?
        let path: String
    }

    private struct Terminal: Decodable {
        let id: String
        let name: String
        let city: String
        let state: String
        let port: String?
        let operators: String
        let railroads: [String]
        let trailers: Bool
        let containers: Bool
        let lat: Double
        let lon: Double
    }

    private struct Service: Decodable {
        struct Railroad: Decodable {
            struct Terminal: Decodable {
                let name: String
                let lat: Double
                let lon: Double
                let dwellHours: Double
            }

            let railroad: String
            let speedMPH: [String: Double]
            let systemDwellHours: Double
            let carsOnline: Int
            let trainsHeldPerDay: Double
            let terminals: [Terminal]
        }

        let weekEnded: String
        let railroads: [Railroad]
    }

    private struct Volume: Decodable {
        struct Figure: Decodable {
            let count: Int
            let changePercent: Double

            var figure: FreightVolumeReport.Figure {
                FreightVolumeReport.Figure(count: count, changePercent: changePercent)
            }
        }

        struct Commodity: Decodable {
            let name: String
            let carloads: Int
            let changePercent: Double
        }

        let week: Int
        let weekEnded: String
        let totalCarloads: Figure
        let intermodalUnits: Figure
        let totalTraffic: Figure
        let commodities: [Commodity]
    }
}
